import{_ as s,c as e,o as i,ag as t}from"./chunks/framework.DQvKz0xt.js";const g=JSON.parse('{"title":"Rive MCP 集成 (Rive MCP Integration) - Rive 编辑器","description":"MCP 处于 早期访问阶段 (Early Access)，尚未公开发布。 MCP 集成目前仅在 macOS 的 Rive Early Access 桌面版应用中提供。Windows 支持即将推出。","frontmatter":{"title":"Rive MCP 集成 (Rive MCP Integration) - Rive 编辑器","description":"MCP 处于 早期访问阶段 (Early Access)，尚未公开发布。 MCP 集成目前仅在 macOS 的 Rive Early Access 桌面版应用中提供。Windows 支持即将推出。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, Rive MCP 集成"}]]},"headers":[],"relativePath":"editor/mcp.md","filePath":"editor/mcp.md","lastUpdated":1774838907000}'),r={name:"editor/mcp.md"};function n(l,a,o,p,c,h){return i(),e("div",null,[...a[0]||(a[0]=[t(`<p>MCP</p><h1 id="rive-mcp-集成-rive-mcp-integration" tabindex="-1">Rive MCP 集成 (Rive MCP Integration) <a class="header-anchor" href="#rive-mcp-集成-rive-mcp-integration" aria-label="Permalink to &quot;Rive MCP 集成 (Rive MCP Integration)&quot;">​</a></h1><p>MCP 处于 <a href="https://rive.app/blog/early-access-to-unreleased-features" target="_blank" rel="noreferrer">早期访问阶段 (Early Access)</a>，尚未公开发布。<br> MCP 集成目前仅在 macOS 的 Rive Early Access 桌面版应用中提供。Windows 支持即将推出。</p><h2 id="​-入门指南-getting-started" tabindex="-1"><a href="#getting-started">​</a> 入门指南 (Getting started) <a class="header-anchor" href="#​-入门指南-getting-started" aria-label="Permalink to &quot;[​](#getting-started) 入门指南 (Getting started)&quot;">​</a></h2><p>你可以通过 <strong>MCP (Model Context Protocol)</strong> 将 Rive 编辑器连接到 AI 工具。首批推出的工具旨在让 AI 替你处理重复性任务，例如创建复杂的视图模型 (View Models)、拥有数百个状态/图层的状态机、响应式布局、以及各种形状等。</p><p>目前此功能仅支持少数支持 MCP 的 AI 工具。我们目前建议使用 <strong>Cursor</strong>，支持列表未来将会扩大。</p><h2 id="​-安装步骤-installation" tabindex="-1"><a href="#installation">​</a> 安装步骤 (Installation) <a class="header-anchor" href="#​-安装步骤-installation" aria-label="Permalink to &quot;[​](#installation) 安装步骤 (Installation)&quot;">​</a></h2><h3 id="​-macos" tabindex="-1"><a href="#mac">​</a> macOS <a class="header-anchor" href="#​-macos" aria-label="Permalink to &quot;[​](#mac) macOS&quot;">​</a></h3><ol><li><strong>安装 Rive Early Access</strong>：下载并安装最新版的 <a href="https://rive.app/downloads" target="_blank" rel="noreferrer">Rive Early Access</a> macOS 桌面版应用。</li><li><strong>设置 Cursor</strong>：创建 <a href="https://www.cursor.com/" target="_blank" rel="noreferrer">Cursor</a> 账号并安装应用。</li><li><strong>保存配置</strong>：在你的电脑上新建一个文件 <code>mcp.json</code>，并将以下 JSON 代码片段存入其中：<div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;rive&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">          &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:9791/sse&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div></li><li><strong>配置 MCP</strong>： <ul><li>如果你在访达 (Finder) 中开启了显示隐藏文件：将 <code>mcp.json</code> 移动到家目录下的 <code>.cursor</code> 文件夹中。</li><li>否则，请打开终端 (Terminal.app) 运行以下命令：<div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /你的路径/mcp.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.cursor</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul></li><li><strong>在 Cursor 中启用</strong>： <ul><li>打开 Cursor 设置面板（右上角图标）。</li><li>导航至 <strong>MCP</strong> 部分。</li><li><strong>验证连接</strong>：如果一切正常，你应该能看到 Rive 已作为一个可用的 MCP 服务器列出。</li><li><em>注意：Rive 服务器必须在 Rive Early Access 应用开启的情况下才可用。</em></li><li>将 MCP 连接设置为 <strong>On</strong>。</li></ul></li></ol><p>更多设置信息可参考 <a href="https://docs.cursor.com/context/model-context-protocol" target="_blank" rel="noreferrer">Cursor 文档</a>。</p><h2 id="​-它可以做什么-what-can-it-do" tabindex="-1"><a href="#what-can-it-do">​</a> 它可以做什么？ (What can it do?) <a class="header-anchor" href="#​-它可以做什么-what-can-it-do" aria-label="Permalink to &quot;[​](#what-can-it-do) 它可以做什么？ (What can it do?)&quot;">​</a></h2><p>一切就绪后，你就可以开始向 AI 发出指令了。</p><ol><li><strong>打开你的 Rive 文件</strong>：保持 Rive 文件开启并已创建一个画板。</li><li><strong>输入 Prompt</strong>：在 Cursor 聊天框输入指令并回车。 例如：<code>Create a State Machine about birds with 20 states and 2 layers</code> (创建一个关于鸟类的状态机，包含 20 个状态和 2 个图层)。</li><li><strong>完成交互</strong>：AI 处理请求后，输入 <strong>End Prompt</strong> 以授权 AI 修改你的 Rive 文件。</li></ol><h3 id="​-支持的功能" tabindex="-1"><a href="#supported-features">​</a> 支持的功能 <a class="header-anchor" href="#​-支持的功能" aria-label="Permalink to &quot;[​](#supported-features) 支持的功能&quot;">​</a></h3><ul><li>创建状态机、图层、状态、过渡和条件。</li><li>创建视图模型、属性和实例。</li><li>创建布局。</li><li>列出视图模型。</li><li>创建图形。</li></ul><p>随着工具的增加，功能列表将不断演进。</p><p><a href="https://help.rive.app/editor/share-links/framer-and-rive" target="_blank" rel="noreferrer">Framer 与 Rive</a><a href="/docs/editor/tagging">标签系统 (Tagging)</a></p>`,17)])])}const u=s(r,[["render",n]]);export{g as __pageData,u as default};
